<?php
$page_title='ตรวจสินค้าผู้ขาย';require_once __DIR__.'/../includes/auth_check.php';requireAdmin();require_once __DIR__.'/../config/database.php';$db=(new Database())->getConnection();$message='';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){requireCsrf(false);$id=(int)($_POST['product_id']??0);$action=$_POST['action']??'';$note=trim((string)($_POST['admin_note']??''));if(!$id||!in_array($action,['approve','reject'],true))$error='ข้อมูลไม่ถูกต้อง';else{$status=$action==='approve'?'approved':'rejected';$stmt=$db->prepare("UPDATE products SET approval_status=?,admin_note=? WHERE id=? AND seller_id IS NOT NULL AND approval_status='pending'");$stmt->execute([$status,$note,$id]);$message=$stmt->rowCount()?'บันทึกสถานะสินค้าแล้ว':'รายการนี้ถูกดำเนินการแล้ว';}}
$products=$db?$db->query('SELECT p.*,u.username,u.full_name,c.name category_name FROM products p JOIN users u ON u.id=p.seller_id JOIN categories c ON c.id=p.category_id WHERE p.seller_id IS NOT NULL ORDER BY FIELD(p.approval_status,"pending","approved","rejected"),p.created_at DESC')->fetchAll():[];require_once __DIR__.'/../includes/admin_header.php';
?><header class="admin-page-header"><div><p class="eyebrow">SELLER PRODUCTS</p><h1>ตรวจสินค้าผู้ขาย</h1><p>อนุมัติสินค้าก่อนให้แสดงบนหน้าร้าน</p></div></header><?php if($message): ?><div class="admin-alert success"><?php echo e($message); ?></div><?php endif;if($error): ?><div class="admin-alert error"><?php echo e($error); ?></div><?php endif;?><section class="admin-panel"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>สินค้า</th><th>ผู้ขาย</th><th>ราคา/สต็อก</th><th>สถานะ</th><th>จัดการ</th></tr></thead><tbody><?php if(!$products): ?><tr><td colspan="5" class="admin-empty">ยังไม่มีสินค้าจากผู้ขาย</td></tr><?php endif;foreach($products as $product): ?><tr><td><img class="admin-thumb" src="<?php echo e(productImageUrl($product['image_url'])); ?>" alt=""><span class="cell-title"><?php echo e($product['name']); ?></span><span class="cell-subtitle"><?php echo e($product['category_name']); ?></span></td><td><?php echo e($product['full_name']?:$product['username']); ?></td><td><?php echo formatCurrency($product['price']); ?><span class="cell-subtitle"><?php echo (int)$product['stock_quantity']; ?> ชิ้น</span></td><td><span class="status-badge <?php echo $product['approval_status']==='approved'?'paid':($product['approval_status']==='rejected'?'cancelled':'pending'); ?>"><?php echo e($product['approval_status']); ?></span></td><td><?php if($product['approval_status']==='pending'): ?><form method="POST" class="table-actions"><input type="hidden" name="csrf_token" value="<?php echo e(getCsrfToken()); ?>"><input type="hidden" name="product_id" value="<?php echo (int)$product['id']; ?>"><input name="admin_note" maxlength="500" placeholder="หมายเหตุ"><button class="btn btn-primary" name="action" value="approve">อนุมัติ</button><button class="btn btn-danger" name="action" value="reject">ปฏิเสธ</button></form><?php else: ?><small><?php echo e($product['admin_note']?:'-'); ?></small><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div></section><?php require_once __DIR__.'/../includes/admin_footer.php'; ?>
